// Porteiro Único — etapa 1: limpar e validar os dados que chegaram.
// Entrada esperada: { nome, email, telefone, origem }
const saida = [];
for (const item of $input.all()) {
  const d = item.json;
  const nome = String(d.nome || '').trim().replace(/\s+/g, ' ');
  // e-mail: minúsculo e validado; inválido = como se não existisse
  let email = String(d.email || '').trim().toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) email = null;
  // telefone: só dígitos, tira o 55 do país; válido com 10 ou 11 dígitos
  let fone = String(d.telefone || '').replace(/\D/g, '');
  if (fone.startsWith('55') && fone.length > 11) fone = fone.slice(2);
  if (fone.length < 10 || fone.length > 11) fone = null;
  // chave imune ao nono dígito: DDD + 8 últimos
  const foneChave = fone ? fone.slice(0, 2) + fone.slice(-8) : null;
  // política selada: sem e-mail E sem telefone válidos → não é lead
  const descartar = !email && !fone;
  const partes = nome.split(' ');
  saida.push({ json: {
    nome,
    primeiroNome: partes[0] || 'Sem nome',
    sobrenome: partes.slice(1).join(' '),
    email, fone, foneChave,
    origem: String(d.origem || '').trim() || 'desconhecida',
    descartar,
  } });
}
return saida;

// Monta a busca no CRM: e-mail exato OU telefone com os mesmos 8 últimos dígitos
const itens = [];
for (const item of $input.all()) {
  const d = item.json;
  const cond = [];
  if (d.email) cond.push({ emails: { primaryEmail: { eq: d.email } } });
  if (d.fone) cond.push({ phones: { primaryPhoneNumber: { ilike: '%' + d.fone.slice(-8) } } });
  itens.push({ json: { ...d, gqlBusca: {
    query: 'query Buscar($filter: PersonFilterInput) { people(filter: $filter, first: 10) { edges { node { id name { firstName lastName } emails { primaryEmail } phones { primaryPhoneNumber } } } } }',
    variables: { filter: cond.length === 1 ? cond[0] : { or: cond } },
  } } });
}
return itens;

// Cruza o resultado da busca com o lead e decide: adotar quem já existe ou criar
const buscas = $('Montar busca').all();
const respostas = $input.all();
const chave = (tel) => {
  let t = String(tel || '').replace(/\D/g, '');
  if (t.startsWith('55') && t.length > 11) t = t.slice(2);
  return t ? t.slice(0, 2) + t.slice(-8) : null;
};
const saida = [];
for (let i = 0; i < respostas.length; i++) {
  const lead = buscas[i].json;
  const encontrados = (respostas[i].json.data?.people?.edges || []).map((e) => e.node);
  // 1º degrau: e-mail exato
  let alvo = lead.email
    ? encontrados.find((p) => (p.emails?.primaryEmail || '').toLowerCase() === lead.email)
    : null;
  let via = alvo ? 'e-mail' : null;
  // 2º degrau: telefone, só em casamento 1↔1 perfeito
  if (!alvo && lead.foneChave) {
    const porFone = encontrados.filter((p) => chave(p.phones?.primaryPhoneNumber) === lead.foneChave);
    if (porFone.length === 1) { alvo = porFone[0]; via = 'telefone'; }
  }
  if (alvo) {
    saida.push({ json: { ...lead, acao: 'adotar', personId: alvo.id, via,
      nomeNoCrm: [alvo.name?.firstName, alvo.name?.lastName].filter(Boolean).join(' ') } });
  } else {
    const data = { name: { firstName: lead.primeiroNome, lastName: lead.sobrenome }, origem: lead.origem };
    if (lead.email) data.emails = { primaryEmail: lead.email };
    if (lead.fone) data.phones = { primaryPhoneNumber: lead.fone, primaryPhoneCallingCode: '+55', primaryPhoneCountryCode: 'BR' };
    saida.push({ json: { ...lead, acao: 'criar', gqlCriar: {
      query: 'mutation Criar($data: PersonCreateInput!) { createPerson(data: $data) { id } }',
      variables: { data },
    } } });
  }
}
return saida;

// Relata o que foi criado (ou o erro, sem travar o fluxo)
const pedidos = $('Decidir').all().filter((p) => p.json.acao === 'criar');
const respostas = $input.all();
const saida = [];
for (let i = 0; i < respostas.length; i++) {
  const lead = pedidos[i].json;
  const erros = respostas[i].json.errors;
  saida.push({ json: erros?.length
    ? { resultado: 'erro', nome: lead.nome, detalhe: erros.map((e) => e.message).join(' | ') }
    : { resultado: 'criado', personId: respostas[i].json.data.createPerson.id, nome: lead.nome, origem: lead.origem } });
}
return saida;
